import unittest
import json
from unittest.mock import patch, MagicMock
from flask.json import dumps


class TestDumps(unittest.TestCase):

    def test_dumps_without_app_context(self):
        """Test dumps function when Flask app context is not available."""
        test_obj = {"key": "value", "number": 42}
        result = dumps(test_obj)
        expected = json.dumps(test_obj)
        self.assertEqual(result, expected)

    @patch('flask.globals.current_app')
    def test_dumps_with_app_context_no_json_provider(self, mock_current_app):
        """Test dumps function when app context exists but has no json provider."""
        # Setup mock app context without json attribute
        type(mock_current_app).json = MagicMock()
        mock_current_app.json.dumps.side_effect = AttributeError

        test_obj = {"test": "data"}
        result = dumps(test_obj)
        expected = json.dumps(test_obj)
        self.assertEqual(result, expected)

    @patch('flask.globals.current_app')
    def test_dumps_with_app_context_with_json_provider(self, mock_current_app):
        """Test dumps function when app context exists with custom json provider."""
        # Setup mock app context with json provider
        mock_current_app.json.dumps.return_value = '{"mocked": "result"}'

        test_obj = {"test": "data"}
        result = dumps(test_obj)

        # Verify the mock was called
        mock_current_app.json.dumps.assert_called_once_with(test_obj)
        self.assertEqual(result, '{"mocked": "result"}')

    def test_dumps_with_kwargs(self):
        """Test dumps function passes kwargs to underlying implementation."""
        test_obj = {"key": "value"}
        result = dumps(test_obj, indent=2, separators=(',', ': '))
        # Should be properly formatted JSON with specified parameters
        expected = json.dumps(test_obj, indent=2, separators=(',', ': '))
        self.assertEqual(result, expected)

    @patch('flask.globals.current_app')
    def test_dumps_with_app_context_and_kwargs(self, mock_current_app):
        """Test dumps function with app context and kwargs."""
        mock_current_app.json.dumps.return_value = '{"formatted": true}'

        test_obj = {"test": "data"}
        kwargs = {'indent': 2}
        result = dumps(test_obj, **kwargs)

        # Verify the mock was called
        mock_current_app.json.dumps.assert_called_once_with(test_obj)
        self.assertEqual(result, '{"formatted": true}')

    def test_dumps_serialization_error(self):
        """Test dumps function raises TypeError for non-serializable objects."""
        class NonSerializable:
            pass

        with self.assertRaises(TypeError):
            dumps(NonSerializable())

    def test_dumps_with_none(self):
        """Test dumps function with None value."""
        result = dumps(None)
        expected = json.dumps(None)
        self.assertEqual(result, expected)

    def test_dumps_with_list(self):
        """Test dumps function with list object."""
        test_obj = [1, 2, 3, "test"]
        result = dumps(test_obj)
        expected = json.dumps(test_obj)
        self.assertEqual(result, expected)

    def test_dumps_with_nested_objects(self):
        """Test dumps function with nested complex objects."""
        test_obj = {
            "users": [
                {"name": "Alice", "age": 30},
                {"name": "Bob", "age": 25}
            ],
            "metadata": {
                "total": 2,
                "active": True
            }
        }
        result = dumps(test_obj)
        expected = json.dumps(test_obj)
        self.assertEqual(result, expected)

    @patch('flask.globals.has_request_context')
    def test_dumps_no_request_context_fallback(self, mock_has_request_context):
        """Test dumps falls back to standard json when no request context."""
        mock_has_request_context.return_value = False

        test_obj = {"fallback": "test"}
